function remove(type,id){const names={card:'card, all its benefits, periods, records and fee history',benefit:'benefit, all its periods and records',record:'record'};if(!confirm(`Permanently delete this ${names[type]}? Export a backup first if you need its history.`))return;const next=structuredClone(data);if(type==='card'){next.cards=next.cards.filter(c=>c.id!==id);next.feeSettings=next.feeSettings.filter(s=>s.cardId!==id);next.feeEntries=next.feeEntries.filter(e=>e.cardId!==id);next.feeReschedules=next.feeReschedules.filter(e=>e.cardId!==id);const ids=next.benefits.filter(b=>b.cardId===id).map(b=>b.id);next.benefits=next.benefits.filter(b=>!ids.includes(b.id));}if(type==='benefit')next.benefits=next.benefits.filter(b=>b.id!==id);next.periods=next.periods.filter(p=>next.benefits.some(b=>b.id===p.benefitId));next.records=next.records.filter(r=>next.periods.some(p=>p.id===r.periodId)&&(type!=='record'||r.id!==id));commit(next);$('#editor').close();notify('Deleted.');}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action],[data-tab]');if(!el)return;if(el.dataset.tab){tab=el.dataset.tab;render();return;}const id=el.dataset.id;switch(el.dataset.action){case 'summary-details':openSummary(id);break;case 'summary-close':$('#summary-browser').close();break;case 'workflow-filter':openWorkflow(id);break;case 'workflow-stage':workflowStage=id;renderWorkflow();break;case 'workflow-close':$('#workflow-browser').close();break;case 'portal-request':portalEditor('request',id);break;case 'portal-request-existing':{const r=data.records.find(r=>r.id===id);portalEditor('request',r.benefitId,id);break;}case 'portal-voucher':portalEditor('voucher',null,id);break;case 'portal-direct':portalEditor('voucher',id);break;case 'portal-outcome':recordEditor(id);break;case 'portal-cancel':cancelEditor(id);break;case 'portal-correct':stageEditor(id);break;case 'portal-resolve-outcome':recordEditor(id,null,true);break;case 'workflow-backup':exportWorkflowBackup();break;case 'clear-summary':$('#summary-from').value='';$('#summary-to').value='';$('#summary-card').value='';render();break;case 'card-fees':feeDetails(id);break;case 'fee-settings':feeSettingsEditor(id);break;case 'fee-anniversary':suggestAnnualDate(true);break;case 'fee-pay-joining':feePaymentEditor(id,'joining');break;case 'fee-pay-annual':feePaymentEditor(id,'annual');break;case 'fee-correct':{const e=data.feeEntries.find(e=>e.id===id);feePaymentEditor(e.cardId,e.kind,e.id);break;}case 'fee-reschedule':feeRescheduleEditor(id);break;case 'template-option':document.querySelector(`.template-options[data-category="${id}"]`).insertAdjacentHTML('beforeend',templateOption(id,{name:'',useValue:null}));break;case 'category-record':categoryRecord(id);break;case 'preferences':preferencesEditor();break;case 'apply-default':applyOptionDefault();break;case 'add-preference':$('.preference-options').insertAdjacentHTML('beforeend',preferenceRow({name:'',useValue:null},$('.preference-options').children.length));break;case 'remove-preference':el.closest('.preference-row').remove();break;case 'review-records':tab='records';$('#search').value='';$('#card-filter').value='';$('#status-filter').value='review';render();break;case 'add-card':cardEditor();break;case 'edit-card':cardEditor(id);break;case 'add-benefit':benefitEditor();break;case 'edit-benefit':benefitEditor(id);break;case 'add-record':portalEditor('voucher',id);break;case 'edit-record':{const r=data.records.find(r=>r.id===id);if(['completed','voucher ready'].includes(stageOf(r,today())))recordEditor(id);else stageEditor(id);break;}break;case 'periods':periodList(id);break;case 'edit-period':periodEditor(id);break;case 'add-period':periodEditor(null,id);break;case 'delete-card':remove('card',id);break;case 'delete-benefit':remove('benefit',id);break;case 'delete-record':remove('record',id);break;case 'close':$('#editor').close();break;case 'legacy-backup':exportLegacy();break;case 'export':exportData();break;case 'backup':backupDialog();break;case 'restore':restoreImport();break;case 'fresh':if(confirm('Replace existing storage with a fresh ledger? This cannot be undone without a backup.')){const next=loadFresh();try{saveData(localStorage,next);storageBlocked=false;data=next;$('#storage-error').hidden=true;$('#save-state').textContent='Saved on this device';render();$('#editor').close();notify('Fresh ledger created.');}catch(e){$('#form-error').textContent=e.message;}}break;}});
import { initialData as loadFresh } from './core.mjs';
for(const id of ['summary-from','summary-to','summary-card'])$('#'+id).addEventListener('change',render);
for(const id of ['workflow-browser-category','workflow-browser-card','workflow-browser-sort'])$('#'+id).addEventListener('change',renderWorkflow);
$('#search').addEventListener('input',render);$('#card-filter').addEventListener('change',render);$('#status-filter').addEventListener('change',render);$('#workflow-filter').addEventListener('change',render);
$('#editor').addEventListener('change',async event=>{const el=event.target;if(el.name==='joiningPaidDate')suggestAnnualDate();if(el.name==='nextDue'&&['fee-settings','card'].includes(editing?.type)){$('#editor-form').dataset.nextDueEdited='true';$('#editor-form').dataset.nextDueAuto='';}if(el.name==='cardType'){const choice=CARD_TYPES.find(t=>t.key===el.value),bank=$('#editor-form').elements.bank;bank.readOnly=choice.key!=='other';bank.value=choice.bank;};if(el.name==='portalCard')populatePortalBenefits(el.value);if(el.name==='portalBenefit')populatePortalPeriods(el.value);if(el.name==='voucherOption')toggleVoucherCustom();if(el.name==='correctStage')toggleCorrectionDate();if(el.name==='feeStatus')updateFeeStatus();if(el.name==='status')updateOutcomeFields();if(el.name==='cardId'&&editing.type==='record'){populateBenefits(el.value);changeRecordBenefit();}if(el.name==='benefitId'&&editing.type==='record')changeRecordBenefit();if(el.name==='periodId')updateRecordReference();if(el.name==='option'&&editing.type==='record'&&!editing.id&&!$('#editor-form').dataset.valueTouched)applyOptionDefault();if(el.name==='prefCategory')preferencesEditor(el.value);if(['sale','received'].includes(el.name))paymentPreview();if(el.id==='import-file'){pendingImport=null;$('#import-preview').textContent='';$('#form-error').textContent='';const file=el.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('Backup exceeds the 5 MB import limit.');pendingImport=validateData(JSON.parse(await file.text()));const d=pendingImport;$('#import-preview').innerHTML=`<p class="import-summary">Valid backup: ${d.cards.length} cards, ${d.benefits.length} benefits, ${d.periods.length} periods, ${d.records.length} records, ${d.feeEntries.length} fee history entries. ${d.records.filter(r=>reviewIssues(r).length).length} need review. Older backups are migrated without guessing provider or actual use values.</p>${button('Replace current ledger…','restore','','button primary')}`;}catch(error){$('#form-error').textContent=error.message;}}});
function restoreImport(){if(!pendingImport||!confirm('Replace ALL current cards, rules, periods, records and fee history with this backup? Export your current data first.'))return;try{const next=syncPeriods(validateData(pendingImport));saveData(localStorage,next);data=next;storageBlocked=false;$('#storage-error').hidden=true;$('#save-state').textContent='Saved on this device';pendingImport=null;render();$('#editor').close();notify('Backup restored and saved.');queueCloudSave();}catch(error){$('#form-error').textContent=`Restore failed; the current ledger was not replaced. ${error.message}`;}}
$('#editor').addEventListener('invalid',event=>{const details=event.target.closest('details');if(details)details.open=true;},true);
$('#editor').addEventListener('input',event=>{if(event.target.name==='useValue')$('#editor-form').dataset.valueTouched='true';if(['sale','received'].includes(event.target.name))paymentPreview();});
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY)storageError('The ledger changed in another tab. Export any unsaved work and reload this tab before making further edits.');if(event.key===STORAGE_KEY)storageBlocked=true;});
window.addEventListener('focus',()=>render());setInterval(render,60000);
